    await expect(
      bridge.loadSession({
        sessionId: 'bad-restore',
        workspaceCwd: WS_A,
      }),
    ).rejects.toBeInstanceOf(SessionNotFoundError);
    expect(handles[0]?.killed).toBe(false);

