    it('releases uploaded media when killSession falls back to a force kill', async () => {
      // A wedged child never answers the kill's cooperative close-notify,
      // so the close request times out and kill takes the force-kill
      // fallback; the media must still be removed immediately instead of
      // degrading to the crash-path detach retention. (A structured
      // RequestError answer is the separate definitive-refusal case, where
      // kill spares the channel and retries later.)
      const close = vi.spyOn(SessionAttachmentStore.prototype, 'close');
      const handle = makeChannel({
        extMethodImpl: (method) => {
          if (method === SERVE_CONTROL_EXT_METHODS.sessionClose) {
            return new Promise(() => {});
          }
          return {};
        },
      });
      const bridge = makeBridge({
        channelFactory: async () => handle.channel,
        initializeTimeoutMs: 20,
      });
      try {
        const session = await bridge.spawnOrAttach({ workspaceCwd: WS_A });
        await bridge.storeSessionAttachment(
          session.sessionId,
          Uint8Array.from([1, 2, 3]),
          'image/png',
          { clientId: session.clientId },
        );

        await expect(bridge.killSession(session.sessionId)).resolves.toBe(true);

        expect(close).toHaveBeenCalledOnce();
        expect(bridge.sessionCount).toBe(0);
      } finally {
        close.mockRestore();
        await bridge.shutdown();
      }
    });

    it('broadcasts prompt_cancelled with originator attribution on cancelSession', async () => {
      // Cross-client sync: a cancel must surface as a first-class event
      // so peer subscribers don't have to infer it from the absence of
      // further agent chunks.
      const factory: ChannelFactory = async () =>
        makeChannel({ promptImpl: () => ({ stopReason: 'end_turn' }) }).channel;
      const bridge = makeBridge({ channelFactory: factory });
      const session = await bridge.spawnOrAttach({ workspaceCwd: WS_A });

      const abort = new AbortController();
      const iter = bridge.subscribeEvents(session.sessionId, {
        signal: abort.signal,
      });
      const firstCancel = (async () => {
        for await (const e of iter) {
          if (e.type === 'prompt_cancelled') return e;
        }
        throw new Error('no prompt_cancelled observed');
      })();

      await bridge.cancelSession(session.sessionId, undefined, {
        clientId: session.clientId,
      });

      const evt = await firstCancel;
      expect(evt.type).toBe('prompt_cancelled');
      expect((evt.data as { sessionId: string }).sessionId).toBe(
        session.sessionId,
      );
      expect(evt.originatorClientId).toBe(session.clientId);

      abort.abort();
      await bridge.shutdown();
    });

    it('deduplicates repeated cancellation broadcasts while idle', async () => {
      const events: BridgeEvent[] = [];
      const handle = makeChannel();
      const bridge = makeBridge({ channelFactory: async () => handle.channel });
      const session = await bridge.spawnOrAttach({ workspaceCwd: WS_A });
      const abort = new AbortController();
      const collecting = (async () => {
        for await (const event of bridge.subscribeEvents(session.sessionId, {
          signal: abort.signal,
        })) {
          if (event.type === 'prompt_cancelled') events.push(event);
        }
      })();

      await bridge.cancelSession(session.sessionId);
      await bridge.cancelSession(session.sessionId);
      await vi.waitFor(() => expect(events).toHaveLength(1));

      abort.abort();
      await collecting;
      await bridge.shutdown();
    });

