    it('resolves pending permissions as cancelled', async () => {
      let capturedConn: AgentSideConnection | undefined;
      const factory: ChannelFactory = async () => {
        const { clientStream, agentStream } = createInMemoryChannel();
        const fakeAgent = new FakeAgent();
        capturedConn = new AgentSideConnection(() => fakeAgent, agentStream);
        return {
          stream: clientStream,
          exited: new Promise<
            | {
                exitCode: number | null;
                signalCode: NodeJS.Signals | null;
              }
            | undefined
          >(() => {}),
          kill: async () => {},
          killSync: () => {},
        };
      };
      const bridge = makeBridge({ channelFactory: factory });
      const session = await bridge.spawnOrAttach({ workspaceCwd: WS_A });
      const conn = capturedConn!;

      const events: BridgeEvent[] = [];
      const drain = (async () => {
        for await (const ev of bridge.subscribeEvents(session.sessionId))
          events.push(ev);
      })();
      await new Promise((r) => setImmediate(r));

      const respPromise = (
        conn as unknown as {
          requestPermission(p: unknown): Promise<unknown>;
        }
      ).requestPermission({
        sessionId: session.sessionId,
        toolCall: { toolCallId: 'tc-1', title: 'rm -rf /' },
        options: [
          { optionId: 'allow', name: 'Allow', kind: 'allow_once' },
          { optionId: 'deny', name: 'Deny', kind: 'reject_once' },
        ],
      });

      await new Promise((r) => setImmediate(r));
      expect(bridge.pendingPermissionCount).toBe(1);

      await bridge.closeSession(session.sessionId);
      await drain;

      const result = (await respPromise) as {
        outcome: { outcome: string };
      };
      expect(result.outcome.outcome).toBe('cancelled');
      expect(bridge.pendingPermissionCount).toBe(0);
      const resolvedIndex = events.findIndex(
        (e) => e.type === 'permission_resolved',
      );
      const closedIndex = events.findIndex((e) => e.type === 'session_closed');
      expect(resolvedIndex).toBeGreaterThanOrEqual(0);
      expect(closedIndex).toBeGreaterThan(resolvedIndex);
      expect(events[resolvedIndex]?.data).toMatchObject({
        outcome: { outcome: 'cancelled' },
      });

      await bridge.shutdown();
    });

    it('tracks a stuck final cancel and retires its channel at the deadline', async () => {
      const stalledWriteStarted = deferred<void>();
      const stalledWrite = deferred<void>();
      const handle = makeChannel();
      const originalWritable = handle.channel.stream.writable;
      let writesBeforeStall = Number.POSITIVE_INFINITY;
      handle.channel.stream = {
        ...handle.channel.stream,
        writable: new WritableStream({
          async write(message) {
            if (writesBeforeStall === 0) {
              stalledWriteStarted.resolve();
              await stalledWrite.promise;
              return;
            }
            writesBeforeStall--;
            const writer = originalWritable.getWriter();
            try {
              await writer.write(message);
            } finally {
              writer.releaseLock();
            }
          },
        }),
      };
      const bridge = makeBridge({
        channelFactory: async () => handle.channel,
        initializeTimeoutMs: 20,
        channelIdleTimeoutMs: 60_000,
      });

      try {
        const session = await bridge.spawnOrAttach({ workspaceCwd: WS_A });
        writesBeforeStall = 1;
        const close = bridge.closeSession(session.sessionId);
        await stalledWriteStarted.promise;

        expect(bridge.getWorkspaceRuntimeLifecycleSnapshot!()).toMatchObject({
          state: 'active',
          runtimeLive: true,
          activeWork: true,
        });
        await expect(close).resolves.toBeUndefined();
        expect(handle.killed).toBe(true);
        await vi.waitFor(() =>
          expect(bridge.getWorkspaceRuntimeLifecycleSnapshot!()).toMatchObject({
            state: 'cold',
            runtimeLive: false,
            activeWork: false,
          }),
        );
      } finally {
        stalledWrite.resolve();
        await bridge.shutdown();
      }
    });

